/* Tauri Specta runtime */
async function typedError<T, E>(
  result: Promise<T>,
): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
  try {
    return { status: "ok", data: await result };
  } catch (e) {
    if (e instanceof Error) throw e;
    return { status: "error", error: e as any };
  }
}

type EventEmit<T> = [T] extends [null]
  ? () => Promise<void>
  : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null]
  ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void>
  : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(
  name: string,
  serialize?: (payload: TEmit) => unknown,
  deserialize?: (payload: any) => TListen,
) {
  const mapEvent =
    (cb: __TAURI_EVENT.EventCallback<TListen>) =>
    (event: __TAURI_EVENT.Event<any>) =>
      cb({
        ...event,
        payload: deserialize ? deserialize(event.payload) : event.payload,
      });
  const mapPayload = (payload: TEmit) =>
    serialize ? serialize(payload) : payload;

  const base = {
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      __TAURI_EVENT.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      __TAURI_EVENT.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) =>
      __TAURI_EVENT.emit(
        name,
        mapPayload(payload),
      ) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
      __TAURI_EVENT.emitTo(
        to,
        name,
        mapPayload(payload),
      ) as unknown) as EventEmitTo<TEmit>,
  };

  const fn = (
    target:
      | import("@tauri-apps/api/webview").Webview
      | import("@tauri-apps/api/window").Window,
  ) => ({
    listen: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      target.listen(name, mapEvent(cb)),
    once: (cb: __TAURI_EVENT.EventCallback<TListen>) =>
      target.once(name, mapEvent(cb)),
    emit: ((payload: TEmit) =>
      target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
    emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
      target.emitTo(
        to,
        name,
        mapPayload(payload),
      ) as unknown) as EventEmitTo<TEmit>,
  });

  return Object.assign(fn, base);
}

/* Tauri Specta mocks */

/** A handler for each generated command, keyed by its `commands` accessor. */
export type MockCommandHandlers = {
  appVersion: (args: {
    request: AppVersionRequest;
  }) => AppVersion | Promise<AppVersion>;
};

/**
 * Install typed mock handlers for the generated commands.
 *
 * Handlers are installed through `@tauri-apps/api/mocks`'s `mockIPC`, so the application
 * under test keeps importing the real `commands` object and still runs the argument and
 * result transforms around each call.
 *
 * A handler receives the command's arguments and returns its success value; throw (or
 * return a rejected promise) to make the command fail. A command with no handler rejects
 * with an error rather than resolving `undefined`, so a test can't pass by accident.
 *
 * Tauri's event mocking is enabled as part of the install (`shouldMockEvents`), so
 * `events` keeps working under test without a second installer fighting this one. Note
 * that Tauri's own mock does not implement `emitTo`, which resolves without reaching any
 * listener. Call `clearMocks` from `@tauri-apps/api/mocks` between tests.
 */
export function mockCommands(
  handlers: Partial<MockCommandHandlers> = {},
): void {
  // A copy with no prototype, so a command named after an `Object.prototype` member
  // (`toString`, `constructor`, …) reports that it is unregistered instead of calling
  // whatever the prototype happens to provide.
  const mockHandlers: Partial<MockCommandHandlers> = Object.create(null);
  Object.assign(mockHandlers, handlers);
  return __TAURI_MOCK_IPC(
    (cmd, args) => {
      switch (cmd) {
        case "app_version":
          return mockCommandHandler(
            mockHandlers.appVersion,
            "app_version",
            args,
          );
        default:
          throw new Error(`No mock handler registered for command '${cmd}'`);
      }
    },
    { shouldMockEvents: true },
  );
}

function mockCommandHandler(
  handler: ((args: any) => unknown) | undefined,
  name: string,
  args: unknown,
): unknown {
  if (handler === undefined)
    throw new Error(`No mock handler registered for command '${name}'`);
  return handler(args);
}
